shellCommands.command:
f=src/DashboardGrid.tsx && sed -i "s/^  raf: number;$/  raf: number;
  preview: Preview | null;/; s/^      raf: requestAnimationFrame(tick),$/      raf: requestAnimationFrame(tick),
      preview: null,/; s/^    setPreview({ kind: it.kind, id: it.id, layout: next, rect });$/    it.preview = { kind: it.kind, id: it.id, layout: next, rect };
    setPreview(it.preview);/; s/^    const result = latest.current.preview;$/    const result = it.preview;/" $f && sed -i "s/, onAnnounce, getLabel, preview });/, onAnnounce, getLabel });/g" $f && grep -n "preview" $f | head -30

mkdir -p /tmp/pwscripts && cat > /tmp/pwscripts/shot.mjs <<'EOF'
import { chromium } from '/tmp/pw/node_modules/playwright/index.mjs';
const out = '/tmp/pwscripts';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1360, height: 1000 } });
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
await page.goto('http://localhost:5179/');
await page.waitForTimeout(800);
await page.screenshot({ path: `${out}/1-initial.png`, fullPage: true });

// hover line chart
const plot = page.locator('.viz-plot');
const pb = await plot.boundingBox();
await page.mouse.move(pb.x + pb.width * 0.6, pb.y + pb.height / 2);
await page.waitForTimeout(150);
await page.screenshot({ path: `${out}/2-hover.png`, clip: { x: pb.x - 40, y: pb.y - 80, width: pb.width + 80, height: pb.height + 100 } });

// drag "orders" header onto the visits chart area (mid-drag screenshot)
const header = page.locator('[data-id="orders"] .widget__title');
const hb = await header.boundingBox();
await page.mouse.move(hb.x + 20, hb.y + 8);
await page.mouse.down();
await page.mouse.move(hb.x + 40, hb.y + 30, { steps: 3 });
await page.mouse.move(hb.x - 300, hb.y + 420, { steps: 12 });
await page.waitForTimeout(300);
await page.screenshot({ path: `${out}/3-dragging.png`, fullPage: true });
await page.mouse.up();
await page.waitForTimeout(400);
await page.screenshot({ path: `${out}/4-dropped.png`, fullPage: true });

// resize channels widget
const handle = page.locator('[data-id="channels"] .grid__resize');
const rb = await handle.boundingBox();
await page.mouse.move(rb.x + 10, rb.y + 10);
await page.mouse.down();
await page.mouse.move(rb.x + 10, rb.y + 200, { steps: 10 });
await page.mouse.up();
await page.waitForTimeout(400);

// keyboard: focus grip of plan widget, move up
await page.locator('[data-grip="plan"]').focus();
await page.keyboard.press('ArrowUp');
await page.waitForTimeout(300);
const focused = await page.evaluate(() => document.activeElement?.getAttribute('data-grip'));
const live = await page.locator('[role=status]').textContent();
await page.screenshot({ path: `${out}/5-after.png`, fullPage: true });

// table view toggle + narrow
await page.locator('[data-id="visits"] button[aria-label="Показать таблицей"]').click();
await page.waitForTimeout(300);
await page.screenshot({ path: `${out}/6-table.png`, fullPage: true });
const saved = await page.evaluate(() => localStorage.getItem('dashboard-state:v1'));
await page.reload();
await page.waitForTimeout(600);
const saved2 = await page.evaluate(() => localStorage.getItem('dashboard-state:v1'));
await page.setViewportSize({ width: 600, height: 900 });
await page.waitForTimeout(500);
await page.screenshot({ path: `${out}/7-narrow.png`, fullPage: true });
console.log(JSON.stringify({ errors, focused, live, persisted: saved === saved2, saved }, null, 1));
await browser.close();
EOF
sleep 2; node /tmp/pwscripts/shot.mjs

sed -i '/^\.viz-bars {$/,/^}$/ s/justify-content: space-around;/justify-content: center;/' src/dashboard.css && sed -i '/^\.viz-bars__row {$/,/^}$/ s/max-height: 48px;/max-height: 44px;/' src/dashboard.css && grep -n "justify-content: center;\|max-height: 44px" src/dashboard.css
cat > /tmp/pwscripts/shot2.mjs <<'EOF'
import { chromium } from '/tmp/pw/node_modules/playwright/index.mjs';
const out = '/tmp/pwscripts';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1360, height: 1000 } });
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
await page.goto('http://localhost:5179/');
await page.evaluate(() => localStorage.clear());
await page.reload();
await page.waitForTimeout(600);
const box = (id) => page.locator(`[data-id="${id}"]`).boundingBox();
const res = {};
// Escape cancels drag
const before = await box('revenue');
const h = await page.locator('[data-id="revenue"] .widget__title').boundingBox();
await page.mouse.move(h.x + 10, h.y + 5); await page.mouse.down();
await page.mouse.move(h.x + 500, h.y + 400, { steps: 10 });
await page.keyboard.press('Escape'); await page.mouse.up(); await page.waitForTimeout(400);
res.escapeRestored = JSON.stringify(before) === JSON.stringify(await box('revenue'));
// hide via menu
await page.locator('[data-id="orders"] button[aria-label="Действия: Заказы"]').click();
await page.getByText('Скрыть виджет').click(); await page.waitForTimeout(400);
res.hiddenGone = (await page.locator('[data-id="orders"]').count()) === 0;
res.conversionMovedLeft = (await box('conversion')).x < 600;
// add back
await page.getByRole('button', { name: 'Добавить виджет' }).click();
await page.getByRole('menuitem', { name: 'Заказы' }).click(); await page.waitForTimeout(400);
res.addedBack = (await page.locator('[data-id="orders"]').count()) === 1;
// min size via keyboard
await page.locator('[data-grip="revenue"]').focus();
for (let i = 0; i < 4; i++) await page.keyboard.press('Shift+ArrowLeft');
await page.waitForTimeout(300);
res.live = await page.locator('[role=status]').textContent();
await page.screenshot({ path: `${out}/8-min.png`, clip: { x: 0, y: 180, width: 1360, height: 640 } });
// 7-day period
await page.getByText('7 дней').click(); await page.waitForTimeout(300);
await page.screenshot({ path: `${out}/9-7days.png`, fullPage: true });
res.errors = errors;
console.log(JSON.stringify(res, null, 1));
await browser.close();
EOF
cd /tmp/pwscripts && FONTCONFIG_FILE=/tmp/debs/fonts.conf LD_LIBRARY_PATH=/tmp/debs/root/usr/lib/aarch64-linux-gnu:/tmp/debs/root/lib/aarch64-linux-gnu node shot2.mjs 2>&1 | tail -20
